\set ON_ERROR_STOP on
DO $$ BEGIN IF current_database()<>'wk_head_rh_permission_test' THEN RAISE EXCEPTION 'isolated fixture required';END IF;END $$;
CREATE SCHEMA IF NOT EXISTS extensions;CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
ALTER TABLE ats_applications ADD COLUMN hiring_details jsonb DEFAULT '{}',ADD COLUMN moved_at timestamptz,ADD COLUMN updated_at timestamptz;
CREATE TYPE public.esign_doc_status AS ENUM('draft','sent','partially_signed','completed','declined','canceled');
CREATE TYPE public.esign_signer_status AS ENUM('pending','viewed','signed','declined');
CREATE TABLE public.esign_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid,workspace_id uuid,title text,body text DEFAULT '',ordered boolean DEFAULT false,status esign_doc_status DEFAULT 'draft',expires_at timestamptz,sent_at timestamptz,completed_at timestamptz);
CREATE TABLE public.esign_signers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid REFERENCES esign_documents(id),owner_id uuid,workspace_id uuid,name text,email text,sign_order integer DEFAULT 1,status esign_signer_status DEFAULT 'pending',public_token text UNIQUE DEFAULT encode(extensions.gen_random_bytes(24),'hex'),signed_name text,signature_data text,ip_address text,user_agent text,viewed_at timestamptz,signed_at timestamptz,declined_at timestamptz,decline_reason text);
CREATE TABLE public.esign_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid REFERENCES esign_documents(id),signer_id uuid,workspace_id uuid,owner_id uuid,event text,ip_address text,user_agent text,metadata jsonb);
CREATE TABLE public.ats_offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid,assigned_to uuid,workspace_id uuid,candidate_id uuid NOT NULL REFERENCES ats_candidates(id),job_id uuid REFERENCES ats_jobs(id),application_id uuid REFERENCES ats_applications(id),title text DEFAULT 'Carta-proposta',body text DEFAULT '',salary_amount numeric,salary_currency text DEFAULT 'BRL',start_date date,status text DEFAULT 'draft' CHECK(status IN('draft','sent','signed','declined','cancelled')),esign_document_id uuid REFERENCES esign_documents(id),promote_to_stage text,sent_at timestamptz,signed_at timestamptz,declined_at timestamptz,viewed_at timestamptz,decline_reason text,public_token text UNIQUE,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.api_keys(id uuid PRIMARY KEY,owner_id uuid,workspace_id uuid,revoked_at timestamptz,expires_at timestamptz,scopes text[]);
ALTER TABLE ats_offers ENABLE ROW LEVEL SECURITY;ALTER TABLE esign_documents ENABLE ROW LEVEL SECURITY;ALTER TABLE esign_signers ENABLE ROW LEVEL SECURITY;ALTER TABLE esign_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY old_esign_all ON esign_documents USING(workspace_id IN(SELECT current_user_workspaces())) WITH CHECK(workspace_id IN(SELECT current_user_workspaces()));
CREATE POLICY old_esign_all ON esign_signers USING(workspace_id IN(SELECT current_user_workspaces())) WITH CHECK(workspace_id IN(SELECT current_user_workspaces()));
CREATE POLICY old_esign_all ON esign_audit USING(workspace_id IN(SELECT current_user_workspaces())) WITH CHECK(workspace_id IN(SELECT current_user_workspaces()));
GRANT SELECT,INSERT,UPDATE,DELETE ON ats_offers,esign_documents,esign_signers,esign_audit TO authenticated,service_role;
INSERT INTO permissions(key,module,resource,action,scope,label_pt) SELECT 'techhire.offers.'||a||'.'||s,'techhire','offers',a::perm_action,s::perm_scope,'Fixture' FROM unnest(ARRAY['view','create','update','delete','approve','export'])a CROSS JOIN unnest(ARRAY['own','team','workspace'])s ON CONFLICT DO NOTHING;
INSERT INTO job_role_permission_overrides(workspace_id,role_id,permission_key,effect,created_by) SELECT '184b9435-0a9b-4334-9e89-8854dc883f5d','aaaaaaaa-0000-4000-8000-000000000004',key,'grant','1c237fbe-079e-4eb9-a3e6-c08d85e79688' FROM permissions WHERE resource='offers' ON CONFLICT DO NOTHING;
UPDATE ats_candidates SET email='fixture@example.test' WHERE id IN('95100000-0000-4000-8000-000000000001','95100000-0000-4000-8000-000000000002');
INSERT INTO ats_offers(id,owner_id,assigned_to,workspace_id,candidate_id,job_id,application_id,title,body,salary_amount) VALUES('99500000-0000-4000-8000-000000000001','90000000-0000-4000-8000-000000000004','90000000-0000-4000-8000-000000000004','184b9435-0a9b-4334-9e89-8854dc883f5d','95100000-0000-4000-8000-000000000002','96000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000001','Private offer','Private letter',9000);
CREATE FUNCTION public.ats_offers_sync_on_esign() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW;END $$;
CREATE TRIGGER trg_ats_offers_sync_on_esign AFTER UPDATE OF status ON public.esign_signers FOR EACH ROW EXECUTE FUNCTION public.ats_offers_sync_on_esign();
